const pages={dashboard:{title:'پیشخوان',view:dashboard},posts:{title:'نوشته‌ها',view:posts},pages:{title:'برگه‌ها',view:pagesView},media:{title:'رسانه',view:media},comments:{title:'دیدگاه‌ها',view:comments},appearance:{title:'پوسته و ظاهر',view:appearance},plugins:{title:'افزونه‌ها',view:plugins},users:{title:'کاربران',view:users},settings:{title:'تنظیمات',view:settings}};
const content=document.querySelector('#app-content'), crumb=document.querySelector('#crumb-title'), toast=document.querySelector('#toast');
function shell(title,desc,action=''){return `<div class="page-title"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function dashboard(){return shell('سلام سعید 👋','نمای کلی از سایت شما، محتوای تازه و وضعیت عملکرد در یک نگاه.','<button class="primary" id="new-post">+ نوشته جدید</button>')+`<div class="stats"><div class="stat"><div class="stat-top"><span>کل نوشته‌ها</span><i class="stat-icon purple">▤</i></div><strong>۱۲۸ <small class="trend">↑ ۸٪</small></strong></div><div class="stat"><div class="stat-top"><span>بازدید این ماه</span><i class="stat-icon green">◉</i></div><strong>۲۴.۶k <small class="trend">↑ ۱۲٪</small></strong></div><div class="stat"><div class="stat-top"><span>کاربران فعال</span><i class="stat-icon orange">♙</i></div><strong>۳,۴۸۲ <small class="trend">↑ ۵٪</small></strong></div><div class="stat"><div class="stat-top"><span>افزونه‌های فعال</span><i class="stat-icon blue">⌘</i></div><strong>۱۸ <small class="trend">+۲ جدید</small></strong></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h3>بازدید سایت</h3><button class="panel-link">۳۰ روز اخیر⌄</button></div><div class="chart">${[34,48,42,66,52,75,61,80,69,92,72,84].map((h,i)=>`<div class="bar" style="height:${h}%"><label>${i+1}</label></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>فعالیت‌های اخیر</h3><button class="panel-link">مشاهده همه</button></div><div class="activity">${[['✎','نوشته «راهنمای شروع» منتشر شد','امروز، ۱۰:۴۲','منتشر شد'],['◌','دیدگاه جدید دریافت شد','امروز، ۰۹:۱۵','در انتظار'],['⚙','افزونه فرم‌ساز به‌روز شد','دیروز، ۱۸:۳۰','انجام شد'],['♙','کاربر جدید ثبت‌نام کرد','دیروز، ۱۶:۰۸','انجام شد']].map(x=>`<div class="activity-row"><i class="activity-icon">${x[0]}</i><div><b>${x[1]}</b><small>${x[2]}</small></div><span class="status ${x[3]==='در انتظار'?'draft':''}">${x[3]}</span></div>`).join('')}</div></section></div><section class="panel" style="margin-top:19px"><div class="panel-head"><h3>دسترسی سریع</h3><span style="font-size:10px;color:#97a1b5">ابزارهای پرکاربرد شما</span></div><div class="quick-actions"><button class="quick" data-page="posts"><strong>✎ نوشتن یک مطلب جدید</strong><small>محتوای تازه برای سایت ایجاد کنید</small></button><button class="quick" data-page="media"><strong>▧ افزودن رسانه</strong><small>تصویر، ویدیو یا فایل جدید آپلود کنید</small></button><button class="quick" data-page="appearance"><strong>✦ شخصی‌سازی ظاهر</strong><small>رنگ‌ها و چیدمان سایت را تنظیم کنید</small></button><button class="quick" data-page="plugins"><strong>⌘ مدیریت افزونه‌ها</strong><small>قابلیت‌های جدید به سایت اضافه کنید</small></button></div></section>`}
function posts(){return shell('نوشته‌ها','همه محتوای سایت را بسازید، سازمان‌دهی کنید و منتشر کنید.','<button class="primary" id="new-post">+ نوشته جدید</button>')+`<section class="panel"><div class="panel-head"><div><button class="panel-link">همه (۱۲۸)</button> <button class="panel-link">منتشرشده (۱۱۵)</button> <button class="panel-link">پیش‌نویس (۱۳)</button></div><button class="ghost">⌕ جست‌وجو</button></div><table class="data-table"><thead><tr><th>عنوان</th><th>نویسنده</th><th>وضعیت</th><th>آخرین ویرایش</th><th></th></tr></thead><tbody>${[['راهنمای شروع کار با نانوپینو','سعید احمدی','منتشرشده','امروز، ۱۰:۴۲'],['۵ راه برای افزایش سرعت سایت','مریم رضایی','منتشرشده','دیروز، ۱۴:۲۰'],['معرفی قابلیت‌های جدید نسخه ۰.۲۴','سعید احمدی','پیش‌نویس','۲ روز پیش'],['چطور یک سایت حرفه‌ای بسازیم؟','علی محمدی','منتشرشده','۳ روز پیش']].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td><span class="tag ${x[2]==='پیش‌نویس'?'draft':''}">${x[2]}</span></td><td>${x[3]}</td><td>⋮</td></tr>`).join('')}</tbody></table></section>`}
function pagesView(){return shell('برگه‌ها','صفحات اصلی سایت و لندینگ‌پیج‌های خود را مدیریت کنید.','<button class="primary" onclick="showToast()">+ برگه جدید</button>')+`<section class="panel"><table class="data-table"><thead><tr><th>عنوان برگه</th><th>نشانی</th><th>وضعیت</th><th>ویرایش</th></tr></thead><tbody>${[['صفحه اصلی','/','منتشرشده','امروز'],['درباره ما','/about','منتشرشده','۵ روز پیش'],['تماس با ما','/contact','منتشرشده','۱ هفته پیش'],['قوانین و حریم خصوصی','/privacy','پیش‌نویس','۲ هفته پیش']].map(x=>`<tr><td><b>${x[0]}</b></td><td style="direction:ltr;text-align:right;color:#8893a8">${x[1]}</td><td><span class="tag ${x[2]==='پیش‌نویس'?'draft':''}">${x[2]}</span></td><td>${x[3]}</td></tr>`).join('')}</tbody></table></section>`}
function media(){return shell('رسانه','کتابخانه مرکزی تصاویر و فایل‌های سایت شما.','<button class="primary" onclick="showToast(\'فایل برای آپلود انتخاب شد\')">↑ آپلود فایل</button>')+`<section class="panel"><div class="empty"><div>▧</div><b>کتابخانه رسانه آماده است</b><p>برای پروتوتایپ، فایل‌های رسانه‌ای شما اینجا نمایش داده می‌شوند.</p></div></section>`}
function comments(){return shell('دیدگاه‌ها','گفت‌وگوی کاربران را مدیریت و پاسخ دهید.')+`<section class="panel"><div class="activity">${['مطلب بسیار مفیدی بود، ممنون از شما!','آیا نسخه ویدیویی این آموزش هم منتشر می‌شود؟','طراحی جدید خیلی تمیز و سریع شده است.'].map((x,i)=>`<div class="activity-row"><span class="avatar">${['م','ن','ک'][i]}</span><div><b>${x}</b><small>کاربر ${['محمد کریمی','نگار حسینی','کیوان رستمی'][i]} · ${i+1} ساعت پیش</small></div><button class="ghost">پاسخ</button></div>`).join('')}</div></section>`}
function appearance(){return shell('پوسته و ظاهر','هویت بصری سایت را با ابزارهای ماژولار نانوپینو بسازید.','<button class="primary" onclick="showToast(\'ویرایشگر ظاهری در نسخه بعدی فعال می‌شود\')">باز کردن ویرایشگر</button>')+`<div class="cards"><section class="panel plugin-card"><div class="plugin-icon">✦</div><h3>پوسته فعال</h3><p>آفتاب — پوسته سبک و واکنش‌گرا برای فروشگاه شما.</p><button class="ghost">سفارشی‌سازی</button></section><section class="panel plugin-card"><div class="plugin-icon">◈</div><h3>رنگ‌های سایت</h3><p>رنگ اصلی، پس‌زمینه و وضعیت‌ها را یک‌جا مدیریت کنید.</p><button class="ghost">مدیریت توکن‌ها</button></section><section class="panel plugin-card"><div class="plugin-icon">▦</div><h3>بلوک‌ها</h3><p>بلوک‌های قابل استفاده مجدد برای ساخت صفحه‌های جدید.</p><button class="ghost">مشاهده کتابخانه</button></section></div>`}
function plugins(){return shell('افزونه‌ها','قابلیت‌های سایت را مثل قطعات لگو فعال و مدیریت کنید.','<button class="primary" onclick="showToast(\'فروشگاه افزونه‌ها به‌زودی\')">+ افزودن افزونه</button>')+`<div class="cards">${[['فرم‌ساز نانو','ساخت فرم‌های حرفه‌ای بدون کدنویسی','۱۸','فرم'],['فروشگاه‌ساز','محصولات، سفارش‌ها و پرداخت آنلاین','۲۴','فروش'],['سئو پلاس','بهینه‌سازی محتوا برای موتورهای جست‌وجو','۶','SEO']].map(x=>`<section class="panel plugin-card"><div class="plugin-icon">⌘</div><h3>${x[0]} <span class="toggle"></span></h3><p>${x[1]}</p><small style="color:#9aa4b7">نسخه ${x[2]} · فعال</small></section>`).join('')}</div>`}
function users(){return shell('کاربران','اعضا، نقش‌ها و دسترسی‌های سایت را کنترل کنید.','<button class="primary" onclick="showToast(\'دعوت‌نامه کاربر ایجاد شد\')">+ دعوت کاربر</button>')+`<section class="panel"><table class="data-table"><thead><tr><th>کاربر</th><th>نقش</th><th>آخرین فعالیت</th><th>وضعیت</th></tr></thead><tbody>${[['سعید احمدی','مدیر کل','همین حالا'],['مریم رضایی','ویرایشگر','امروز، ۰۹:۴۳'],['علی محمدی','نویسنده','دیروز، ۱۸:۲۰']].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td><span class="tag">فعال</span></td></tr>`).join('')}</tbody></table></section>`}
function settings(){return shell('تنظیمات','تنظیمات پایه سایت و ماژول‌های فعال پینوکس.')+`<div class="settings-list"><div class="setting"><div><b>نام سایت</b><small>عنوانی که در سربرگ سایت نمایش داده می‌شود</small></div><strong>فروشگاه آفتاب ✎</strong></div><div class="setting"><div><b>حالت تعمیر و نگهداری</b><small>نمایش پیام موقت به بازدیدکنندگان</small></div><span class="toggle" style="background:#dfe3ed"></span></div><div class="setting"><div><b>زبان پیش‌فرض</b><small>زبان پنل و محتوای مدیریتی</small></div><strong>فارسی (RTL)⌄</strong></div></div>`}
function render(key='dashboard'){const p=pages[key]||pages.dashboard;crumb.textContent=p.title;content.innerHTML=p.view();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===key));bind()}function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>render(b.dataset.page));document.querySelector('#new-post')?.addEventListener('click',()=>document.querySelector('#post-dialog').showModal());}function showToast(msg='تغییرات ذخیره شد'){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}document.querySelector('#post-form').addEventListener('submit',e=>{e.preventDefault();document.querySelector('#post-dialog').close();showToast('پیش‌نویس ذخیره شد')});render();document.querySelector('#command-search')?.addEventListener('click',()=>showToast('جست‌وجوی سریع آماده است — از منوی سمت راست یک بخش را انتخاب کنید'));document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#command-search')?.focus();showToast('جست‌وجوی سریع را شروع کنید')}});
